static const char* const RT_PIPELINE_SPV_FILES[] = {
    "shaders\\rt_test.rgen.spv",
    "shaders\\rt_test_ser.rgen.spv",
    "shaders\\rt_test.rchit.spv",
    "shaders\\rt_test.rmiss.spv",
    "shaders\\rt_test.rahit.spv",
    "shaders\\rt_test_translucent.rchit.spv",
    "shaders\\rt_test_translucent.rahit.spv",
    "shaders\\rr_guide_relax.comp.spv",
};

static const size_t PIPELINE_CACHE_MAX_RESTORE_BYTES =
    64u * 1024u * 1024u;

static std::string ComputeRTPipelineCacheKey()
{
    const std::string directory =
        GetRTXBackendDirectory();

    if(directory.empty())
    {
        return {};
    }

    uint64_t hash = 1469598103934665603ull;

    const auto fold = [&hash](const void* data, size_t size)
    {
        const unsigned char* bytes =
            static_cast<const unsigned char*>(data);

        for(size_t i = 0; i < size; ++i)
        {
            hash ^= static_cast<uint64_t>(bytes[i]);
            hash *= 1099511628211ull;
        }
    };

    for(const char* relative : RT_PIPELINE_SPV_FILES)
    {
        fold(relative, std::strlen(relative));

        const std::string fullPath =
            directory + "\\" + relative;

        std::ifstream f(
            fullPath,
            std::ios::binary |
            std::ios::ate
        );

        if(!f)
        {
            continue;
        }

        const std::streamsize size = f.tellg();

        f.seekg(0, std::ios::beg);

        std::vector<char> bytes(
            size > 0
                ? static_cast<size_t>(size)
                : 0u
        );

        if(!bytes.empty())
        {
            f.read(
                bytes.data(),
                static_cast<std::streamsize>(bytes.size())
            );

            fold(bytes.data(), bytes.size());
        }
    }

    char text[32] = {};

    std::snprintf(
        text,
        sizeof(text),
        "%016llx",
        static_cast<unsigned long long>(hash)
    );

    return std::string(text);
}

static std::string GetPipelineCacheFilePath()
{
    static const std::string cachedPath = []() -> std::string
    {
        const std::string directory =
            GetRTXBackendDirectory();

        if(directory.empty())
        {
            return {};
        }

        const std::string key =
            ComputeRTPipelineCacheKey();

        if(key.empty())
        {
            return directory + "\\rtx_pipeline_cache.bin";
        }

        return
            directory +
            "\\rtx_pipeline_cache_" +
            key +
            ".bin";
    }();

    return cachedPath;
}



static const uint32_t PIPELINE_CACHE_KEEP_SEEDS = 3u;
static const size_t PIPELINE_CACHE_SEED_BUDGET_BYTES =
    96u * 1024u * 1024u;

// 目录里除 keepPath 之外、最近的 maxCount 份 rtx_pipeline_cache*.bin（mtime 降序）。
static std::vector<std::string> FindNewestOtherPipelineCaches(
    const std::string& keepPath,
    uint32_t maxCount
)
{
    std::vector<std::string> out;

    const std::string directory = GetRTXBackendDirectory();

    if(directory.empty() || maxCount == 0u)
    {
        return out;
    }

    const std::string pattern =
        directory + "\\rtx_pipeline_cache*.bin";

    WIN32_FIND_DATAA entry = {};
    HANDLE search =
        FindFirstFileA(pattern.c_str(), &entry);

    if(search == INVALID_HANDLE_VALUE)
    {
        return out;
    }

    struct Candidate
    {
        uint64_t writeTime = 0u;
        size_t size = 0u;
        std::string path;
    };

    std::vector<Candidate> candidates;

    do
    {
        if((entry.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) != 0)
        {
            continue;
        }

        const std::string candidatePath =
            directory + "\\" + entry.cFileName;

        if(_stricmp(candidatePath.c_str(), keepPath.c_str()) == 0)
        {
            continue;
        }

        const size_t size =
            (static_cast<size_t>(entry.nFileSizeHigh) << 32) |
            static_cast<size_t>(entry.nFileSizeLow);

        if(size == 0u)
        {
            continue;
        }

        Candidate candidate;
        candidate.writeTime =
            (static_cast<uint64_t>(entry.ftLastWriteTime.dwHighDateTime) << 32) |
            static_cast<uint64_t>(entry.ftLastWriteTime.dwLowDateTime);
        candidate.size = size;
        candidate.path = candidatePath;

        candidates.push_back(std::move(candidate));
    }
    while(FindNextFileA(search, &entry));

    FindClose(search);

    std::sort(
        candidates.begin(),
        candidates.end(),
        [](const Candidate& a, const Candidate& b)
        {
            return a.writeTime > b.writeTime;
        }
    );

    size_t budget = PIPELINE_CACHE_SEED_BUDGET_BYTES;

    for(const Candidate& candidate : candidates)
    {
        if(out.size() >= maxCount)
        {
            break;
        }

        if(candidate.size > budget)
        {
            continue;
        }

        budget -= candidate.size;
        out.push_back(candidate.path);
    }

    return out;
}

// 读一个缓存文件到 outData（0 字节或读失败返回 false）。与 getSharedPipelineCache
// 里读当前键文件用的是同一套逻辑，抽出来共用。
static bool LoadPipelineCacheFile(
    const std::string& path,
    std::vector<uint8_t>& outData)
{
    FILE* file = fopen(path.c_str(), "rb");

    if(file == nullptr)
    {
        return false;
    }

    if(fseek(file, 0, SEEK_END) == 0)
    {
        const long size = ftell(file);

        if(size > 0 &&
           fseek(file, 0, SEEK_SET) == 0)
        {
            outData.resize(static_cast<size_t>(size));

            const size_t read = fread(
                outData.data(),
                1,
                outData.size(),
                file
            );

            outData.resize(read);
        }
    }

    fclose(file);

    return !outData.empty();
}

// Deletes every rtx_pipeline_cache*.bin except the one this session uses.  That
// includes the unsuffixed name Perf-PC.1/PC.2 wrote, which is how the 78.8 MB
// blob from the keyed build's first launch gets cleared out.
//
// 2026-10-07（Perf-PC.4）：**保留最新的那个旧键文件**，它是下一版缓存的增量种子。
static void DeleteStalePipelineCaches()
{
    const std::string keepPath =
        GetPipelineCacheFilePath();

    const std::string directory =
        GetRTXBackendDirectory();

    if(keepPath.empty() || directory.empty())
    {
        return;
    }

    const std::string pattern =
        directory + "\\rtx_pipeline_cache*.bin";

    WIN32_FIND_DATAA entry = {};

    HANDLE search =
        FindFirstFileA(pattern.c_str(), &entry);

    if(search == INVALID_HANDLE_VALUE)
    {
        return;
    }

    size_t removedCount = 0;
    size_t removedBytes = 0;

    const std::vector<std::string> seedKeepPaths =
        FindNewestOtherPipelineCaches(keepPath, PIPELINE_CACHE_KEEP_SEEDS);

    do
    {
        if((entry.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) != 0)
        {
            continue;
        }

        const std::string candidate =
            directory + "\\" + entry.cFileName;

        if(_stricmp(candidate.c_str(), keepPath.c_str()) == 0)
        {
            continue;
        }

        bool keepAsSeed = false;

        for(const std::string& seedPath : seedKeepPaths)
        {
            if(_stricmp(candidate.c_str(), seedPath.c_str()) == 0)
            {
                keepAsSeed = true;
                break;
            }
        }

        if(keepAsSeed)
        {
            continue;
        }

        const size_t size =
            (static_cast<size_t>(entry.nFileSizeHigh) << 32) |
            static_cast<size_t>(entry.nFileSizeLow);

        if(DeleteFileA(candidate.c_str()))
        {
            ++removedCount;
            removedBytes += size;
        }
    }
    while(FindNextFileA(search, &entry));

    FindClose(search);

    if(removedCount > 0)
    {
        fprintf(
            stderr,
            "[PERF PC.3] stale pipeline caches removed count=%zu bytes=%zu keep=%s\n",
            removedCount,
            removedBytes,
            keepPath.c_str()
        );

        fflush(stderr);

        RTLog(
            "[PERF PC.3] stale pipeline caches removed count=" +
            std::to_string(removedCount) +
            " bytes=" +
            std::to_string(removedBytes)
        );
    }
}

static VkPipelineCache getSharedPipelineCache()
{
    if(g_pipelineCache != VK_NULL_HANDLE)
    {
        return g_pipelineCache;
    }

    if(g_device == VK_NULL_HANDLE)
    {
        return VK_NULL_HANDLE;
    }

    std::vector<uint8_t> initialData;

    const std::string path =
        GetPipelineCacheFilePath();

    DeleteStalePipelineCaches();

    if(!path.empty())
    {
        LoadPipelineCacheFile(path, initialData);
    }

    std::vector<std::string> mergeSeedPaths;

    if(initialData.empty() && !path.empty())
    {
        const std::vector<std::string> seedPaths =
            FindNewestOtherPipelineCaches(path, PIPELINE_CACHE_KEEP_SEEDS);

        if(!seedPaths.empty())
        {
            std::vector<uint8_t> seedData;

            if(LoadPipelineCacheFile(seedPaths[0], seedData))
            {
                initialData.swap(seedData);

                fprintf(
                    stderr,
                    "[PERF PC.4] incremental seed from %s bytes=%zu\n",
                    seedPaths[0].c_str(),
                    initialData.size()
                );

                fflush(stderr);

                RTLog(
                    "[PERF PC.4] incremental seed bytes=" +
                    std::to_string(initialData.size())
                );

                for(size_t i = 1u; i < seedPaths.size(); ++i)
                {
                    mergeSeedPaths.push_back(seedPaths[i]);
                }
            }
        }
    }

    if(initialData.size() > PIPELINE_CACHE_MAX_RESTORE_BYTES)
    {
        fprintf(
            stderr,
            "[PERF PC.3] pipeline cache oversized, starting empty bytes=%zu path=%s\n",
            initialData.size(),
            path.c_str()
        );

        fflush(stderr);

        RTLog(
            "[PERF PC.3] pipeline cache oversized, starting empty bytes=" +
            std::to_string(initialData.size())
        );

        initialData.clear();

        DeleteFileA(path.c_str());
    }

    VkPipelineCacheCreateInfo createInfo{
        VK_STRUCTURE_TYPE_PIPELINE_CACHE_CREATE_INFO
    };

    createInfo.initialDataSize = initialData.size();
    createInfo.pInitialData =
        initialData.empty()
            ? nullptr
            : initialData.data();

    VkResult result = vkCreatePipelineCache(
        g_device,
        &createInfo,
        nullptr,
        &g_pipelineCache
    );

    if(result != VK_SUCCESS && !initialData.empty())
    {
        g_pipelineCache = VK_NULL_HANDLE;
        initialData.clear();

        VkPipelineCacheCreateInfo emptyInfo{
            VK_STRUCTURE_TYPE_PIPELINE_CACHE_CREATE_INFO
        };

        result = vkCreatePipelineCache(
            g_device,
            &emptyInfo,
            nullptr,
            &g_pipelineCache
        );
    }

    if(result != VK_SUCCESS)
    {
        g_pipelineCache = VK_NULL_HANDLE;

        fprintf(
            stderr,
            "[PERF PC.1] vkCreatePipelineCache failed result=%d\n",
            static_cast<int>(result)
        );

        fflush(stderr);

        return VK_NULL_HANDLE;
    }

    if(!initialData.empty())
    {
        fprintf(
            stderr,
            "[PERF PC.1] pipeline cache restored bytes=%zu path=%s\n",
            initialData.size(),
            path.c_str()
        );

        RTLog(
            "[PERF PC.1] pipeline cache restored bytes=" +
            std::to_string(initialData.size())
        );
    }
    else
    {
        fprintf(
            stderr,
            "[PERF PC.1] pipeline cache created empty path=%s\n",
            path.empty() ? "<none>" : path.c_str()
        );

        RTLog(
            "[PERF PC.1] pipeline cache created empty path=" +
            (path.empty() ? std::string("<none>") : path)
        );
    }

    if(!mergeSeedPaths.empty() && g_pipelineCache != VK_NULL_HANDLE)
    {
        size_t mergedCount = 0u;
        size_t mergedBytes = 0u;

        for(const std::string& seedPath : mergeSeedPaths)
        {
            std::vector<uint8_t> seedData;

            if(!LoadPipelineCacheFile(seedPath, seedData) || seedData.empty())
            {
                continue;
            }

            VkPipelineCacheCreateInfo seedInfo{
                VK_STRUCTURE_TYPE_PIPELINE_CACHE_CREATE_INFO
            };

            seedInfo.initialDataSize = seedData.size();
            seedInfo.pInitialData = seedData.data();

            VkPipelineCache seedCache = VK_NULL_HANDLE;

            if(vkCreatePipelineCache(
                   g_device,
                   &seedInfo,
                   nullptr,
                   &seedCache) != VK_SUCCESS ||
               seedCache == VK_NULL_HANDLE)
            {
                continue;
            }

            if(vkMergePipelineCaches(
                   g_device,
                   g_pipelineCache,
                   1u,
                   &seedCache) == VK_SUCCESS)
            {
                ++mergedCount;
                mergedBytes += seedData.size();
            }

            vkDestroyPipelineCache(g_device, seedCache, nullptr);
        }

        if(mergedCount > 0u)
        {
            fprintf(
                stderr,
                "[PERF PC.5] merged extra seeds count=%zu bytes=%zu\n",
                mergedCount,
                mergedBytes
            );

            fflush(stderr);

            RTLog(
                "[PERF PC.5] merged extra seeds count=" +
                std::to_string(mergedCount) +
                " bytes=" +
                std::to_string(mergedBytes)
            );
        }
    }

    fflush(stderr);

    return g_pipelineCache;
}

static void persistSharedPipelineCache()
{
    if(g_pipelineCache == VK_NULL_HANDLE || g_device == VK_NULL_HANDLE)
    {
        return;
    }

    size_t blobSize = 0;

    if(vkGetPipelineCacheData(
           g_device,
           g_pipelineCache,
           &blobSize,
           nullptr) != VK_SUCCESS ||
       blobSize == 0)
    {
        return;
    }

    std::vector<uint8_t> blob(blobSize);

    if(vkGetPipelineCacheData(
           g_device,
           g_pipelineCache,
           &blobSize,
           blob.data()) != VK_SUCCESS)
    {
        return;
    }

    const std::string path =
        GetPipelineCacheFilePath();

    if(path.empty())
    {
        return;
    }

    FILE* file = fopen(path.c_str(), "wb");

    if(file)
    {
        const size_t written = fwrite(
            blob.data(),
            1,
            blobSize,
            file
        );

        fclose(file);

        fprintf(
            stderr,
            "[PERF PC.1] pipeline cache saved bytes=%zu\n",
            written
        );

        RTLog(
            "[PERF PC.1] pipeline cache saved bytes=" +
            std::to_string(written)
        );
    }
    else
    {
        fprintf(
            stderr,
            "[PERF PC.1] pipeline cache save failed path=%s\n",
            path.c_str()
        );

        RTLog(
            "[PERF PC.1] pipeline cache save failed path=" +
            path
        );
    }

    fflush(stderr);
}

static size_t g_pipelineCachePersistedBytes = 0;
static uint32_t g_pipelineCachePersistCountdown = 60;
static const uint32_t PIPELINE_CACHE_PERSIST_INTERVAL = 1800;

static void maybePersistSharedPipelineCache()
{
    if(g_pipelineCachePersistCountdown > 0u)
    {
        --g_pipelineCachePersistCountdown;

        return;
    }

    g_pipelineCachePersistCountdown =
        PIPELINE_CACHE_PERSIST_INTERVAL;

    if(g_pipelineCache == VK_NULL_HANDLE || g_device == VK_NULL_HANDLE)
    {
        return;
    }

    size_t blobSize = 0;

    if(vkGetPipelineCacheData(
           g_device,
           g_pipelineCache,
           &blobSize,
           nullptr) != VK_SUCCESS ||
       blobSize == 0 ||
       blobSize == g_pipelineCachePersistedBytes)
    {
        return;
    }

    persistSharedPipelineCache();

    g_pipelineCachePersistedBytes = blobSize;
}

static void releaseSharedPipelineCache()
{
    if(g_pipelineCache != VK_NULL_HANDLE)
    {
        persistSharedPipelineCache();

        if(g_device != VK_NULL_HANDLE)
        {
            vkDestroyPipelineCache(
                g_device,
                g_pipelineCache,
                nullptr
            );
        }

        g_pipelineCache = VK_NULL_HANDLE;
        g_pipelineCachePersistedBytes = 0;
        g_pipelineCachePersistCountdown = 60;
    }
}


constexpr uint32_t PERF_L10_ABLATION_OFF = 0xffffffffu;
constexpr uint32_t PERF_L10_ABLATION_SWEEP = 0xfffffffeu;
constexpr uint32_t PERF_L10_ABLATION_ALT_FLAG = 0x80000000u;
constexpr uint32_t PERF_L10_ABLATION_ALT_MAX = 16u;

static std::vector<uint32_t> g_perfL10AblationAltStages;

// 解析一次并缓存（同 perfTimestampsEnabled：改完必须重启客户端）。
static uint32_t perfL10AblationRequestedStage()
{
    static const uint32_t request = []() -> uint32_t
    {
        const char* raw = std::getenv("ORION_PERF_ABLATION");
        if(raw == nullptr || std::string(raw) == "0")
        {
            return PERF_L10_ABLATION_OFF;
        }
        const std::string text(raw);
        const std::size_t alt = text.find("alt:");
        if(alt != std::string::npos)
        {
            std::string list = text.substr(alt + 4);
            std::size_t begin = 0u;
            while(begin <= list.size() &&
                  g_perfL10AblationAltStages.size() < PERF_L10_ABLATION_ALT_MAX)
            {
                const std::size_t comma = list.find(',', begin);
                const std::string item = list.substr(
                    begin,
                    comma == std::string::npos ? std::string::npos : comma - begin);
                const int value = std::atoi(item.c_str());
                if(value >= 0)
                {
                    g_perfL10AblationAltStages.push_back(
                        static_cast<uint32_t>(value % 34));
                }
                if(comma == std::string::npos)
                {
                    break;
                }
                begin = comma + 1u;
            }
            return PERF_L10_ABLATION_ALT_FLAG;
        }
        const std::size_t colon = text.find("pin:");
        if(colon == std::string::npos)
        {
            return PERF_L10_ABLATION_SWEEP;
        }
        const int value = std::atoi(text.c_str() + colon + 4);
        if(value < 0)
        {
            return PERF_L10_ABLATION_SWEEP;
        }
        return static_cast<uint32_t>(value % 34);
    }();
    return request;
}

static bool perfL10AblationEnabled()
{
    return perfL10AblationRequestedStage() != PERF_L10_ABLATION_OFF;
}

static bool perfL10AblationAltMode(uint32_t request)
{
    return (request & PERF_L10_ABLATION_ALT_FLAG) != 0u;
}


constexpr uint64_t PERF_L10_ABLATION_FRAMES_PER_STAGE = 120u;
