constexpr double SECTION_REBUILD_TIME_BUDGET_MS = 5.0;
constexpr double SECTION_REBUILD_TIME_BUDGET_ADAPTIVE_MAX_MS = 12.0;
constexpr double SECTION_REBUILD_TIME_BUDGET_GPU_FRACTION = 0.70;
constexpr uint64_t SECTION_REBUILD_CONTINUE_FRAMES = 3u;

static size_t g_sectionRebuildBatchCap = SECTION_REBUILD_MAX_SECTIONS_PER_BATCH;
static bool g_sectionRebuildInterrupted = false;
