static float waterSimUpdateSeconds()
{
    static const float cached = []() -> float
    {
        const char* raw = std::getenv("ORION_WATER_SIM_HZ");

        int hz = 15;

        if(raw != nullptr)
        {
            const int parsed = std::atoi(raw);

            if(parsed >= 15 && parsed <= 60)
            {
                hz = parsed;
            }
        }

        return 1.0f / static_cast<float>(hz);
    }();

    return cached;
}

