static jobjectArray
FGMakeJavaStringArray(
    JNIEnv* env,
    const std::vector<std::string>& values
)
{
    jclass stringClass =
        env->FindClass(
            "java/lang/String"
        );


    if(!stringClass)
    {
        return nullptr;
    }


    jobjectArray result =
        env->NewObjectArray(
            static_cast<jsize>(
                values.size()
            ),
            stringClass,
            nullptr
        );


    if(!result)
    {
        env->DeleteLocalRef(
            stringClass
        );

        return nullptr;
    }


    for(
        size_t i = 0;
        i < values.size();
        ++i
    )
    {
        jstring value =
            env->NewStringUTF(
                values[i].c_str()
            );


        if(value)
        {
            env->SetObjectArrayElement(
                result,
                static_cast<jsize>(i),
                value
            );


            env->DeleteLocalRef(
                value
            );
        }
    }


    env->DeleteLocalRef(
        stringClass
    );


    return result;
}
